<!--
 * SAML IdP 配置管理页面 — 管理 SAML 身份提供商配置
 *
 * @path apps\userinfo-web\src\views\saml-idp\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * SAML IdP 配置管理（列表页）
 * <p>SAML 身份提供商配置的列表页，消费后端契约 SamlIdpConfigController
 * （src/api/samlIdpConfig.ts，auto-generated by bash/gen-contract.py）：
 * page() 分页查询 IdP 配置列表，支持创建/编辑/启用禁用/删除等操作。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import {
  ElButton,
  ElForm,
  ElFormItem,
  ElInput,
  ElInputNumber,
  ElMessage,
  ElMessageBox,
  ElRadioButton,
  ElRadioGroup,
  ElTag,
} from 'element-plus';
import { computed, h, reactive, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { createLogger } from '@YDSZ-core/shared/utils';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { create, deleteApi, page, update } from '#/api/samlIdpConfig';
import type { SamlIdpConfigVO, SamlIdpDTO } from '#/api/models';

defineOptions({ name: 'SamlIdpManagement' });

const logger = createLogger('userinfo-saml-idp');
const { t } = useI18n();

/** IdP 状态判断 */
function isEnabled(status?: string): boolean {
  return status === 'ENABLED';
}

// ========== VxeTable 配置 ==========
const gridOptions: VxeTableGridOptions<SamlIdpConfigVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'entityId', title: 'Entity ID', minWidth: 220 },
    { field: 'name', title: 'IdP 名称', width: 160 },
    { field: 'ssoUrl', title: 'SSO 端点', minWidth: 200 },
    {
      field: 'status',
      title: '状态',
      width: 80,
      slots: {
        default: ({ row }) => {
          const enable = isEnabled(row.status);
          return h(
            ElTag,
            { type: enable ? 'success' : 'danger', size: 'small' },
            () => (enable ? t('page.enabled') : t('page.disabled')),
          );
        },
      },
    },
    { field: 'createdAt', title: '创建时间', width: 170 },
    {
      field: 'action',
      title: '操作',
      width: 220,
      fixed: 'right',
      slots: {
        default: ({ row }) =>
          h('div', { class: 'flex gap-1 flex-wrap' }, [
            h(
              ElButton,
              { size: 'small', link: true, type: 'primary', onClick: () => handleEdit(row) },
              () => t('page.edit'),
            ),
            h(
              ElButton,
              {
                size: 'small',
                link: true,
                type: isEnabled(row.status) ? 'warning' : 'success',
                onClick: () => handleToggleStatus(row),
              },
              () => (isEnabled(row.status) ? '禁用' : '启用'),
            ),
            h(
              ElButton,
              { size: 'small', link: true, type: 'danger', onClick: () => handleDelete(row) },
              () => t('page.delete'),
            ),
          ]),
      },
    },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await page({
          query: {
            status: formValues?.status || undefined,
            name: formValues?.name || undefined,
          },
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
};

const [Grid, gridApi] = useYDSZVxeGrid({
  gridOptions,
  formOptions: {
    schema: [
      {
        component: 'Input',
        componentProps: { placeholder: 'IdP 名称' },
        fieldName: 'name',
        label: '名称',
      },
      {
        component: 'Select',
        componentProps: {
          placeholder: t('page.status'),
          options: [
            { label: '已启用', value: 'ENABLED' },
            { label: '已停用', value: 'DISABLED' },
          ],
        },
        fieldName: 'status',
        label: t('page.status'),
      },
    ],
    submitOnChange: false,
    collapsed: false,
    collapseTriggerResize: true,
    showCollapseButton: true,
    submitButtonOptions: { content: t('page.search') },
    resetButtonOptions: { content: t('page.reset') },
  },
});

// ========== 表单弹窗 ==========
const formRef = ref();
const isEdit = ref(false);

interface SamlIdpFormState {
  entityId: string;
  name: string;
  ssoUrl: string;
  certificate: string;
  emailAttribute: string;
  displayNameAttribute: string;
  status: string;
  sortOrder: number;
  remark: string;
}

const formData = reactive<SamlIdpFormState>({
  entityId: '',
  name: '',
  ssoUrl: '',
  certificate: '',
  emailAttribute: 'email',
  displayNameAttribute: 'displayName',
  status: 'ENABLED',
  sortOrder: 0,
  remark: '',
});

const rules = {
  entityId: [{ required: true, message: '请输入 Entity ID', trigger: 'blur' }],
  name: [{ required: true, message: '请输入 IdP 名称', trigger: 'blur' }],
  ssoUrl: [{ required: true, message: '请输入 SSO 端点 URL', trigger: 'blur' }],
};

const [Modal, modalApi] = useYDSZModal({
  onOpenChange: (isOpen: boolean) => {
    if (!isOpen) return;
    const data = modalApi.getData<{ record?: SamlIdpConfigVO }>();
    if (data?.record) {
      isEdit.value = true;
      Object.assign(formData, {
        entityId: data.record.entityId ?? '',
        name: data.record.name ?? '',
        ssoUrl: data.record.ssoUrl ?? '',
        certificate: data.record.certificate ?? '',
        emailAttribute: data.record.emailAttribute ?? 'email',
        displayNameAttribute: data.record.displayNameAttribute ?? 'displayName',
        status: data.record.status ?? 'ENABLED',
        sortOrder: data.record.sortOrder ?? 0,
        remark: data.record.remark ?? '',
      });
    } else {
      isEdit.value = false;
      Object.assign(formData, {
        entityId: '',
        name: '',
        ssoUrl: '',
        certificate: '',
        emailAttribute: 'email',
        displayNameAttribute: 'displayName',
        status: 'ENABLED',
        sortOrder: 0,
        remark: '',
      });
    }
  },
  onConfirm: async () => {
    try {
      await formRef.value?.validate();
    } catch (error) {
      logger.warn('表单校验失败: {}', error);
      return;
    }
    modalApi.lock();
    try {
      const payload: SamlIdpDTO = {
        entityId: formData.entityId,
        name: formData.name,
        ssoUrl: formData.ssoUrl,
        certificate: formData.certificate,
        emailAttribute: formData.emailAttribute,
        displayNameAttribute: formData.displayNameAttribute,
        status: formData.status,
        sortOrder: formData.sortOrder,
        remark: formData.remark,
      };
      if (isEdit.value) {
        await update({ entityId: formData.entityId }, payload);
        ElMessage.success('更新成功');
      } else {
        await create(payload);
        ElMessage.success('创建成功');
      }
      modalApi.close();
      gridApi.query();
    } catch (error) {
      logger.warn('保存 SAML IdP 配置失败: {}', error);
    } finally {
      modalApi.unlock();
    }
  },
});

const modalTitle = computed(() => (isEdit.value ? '编辑 SAML IdP 配置' : '创建 SAML IdP 配置'));

function handleAdd() {
  modalApi.setData({});
  modalApi.open();
}

function handleEdit(row: SamlIdpConfigVO) {
  modalApi.setData({ record: row });
  modalApi.open();
}

async function handleToggleStatus(row: SamlIdpConfigVO) {
  if (!row.entityId) return;
  const newStatus = isEnabled(row.status) ? 'DISABLED' : 'ENABLED';
  try {
    await ElMessageBox.confirm(
      `确认${isEnabled(row.status) ? '禁用' : '启用'} IdP "${row.name ?? row.entityId}"？`,
      '确认操作',
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    await update({ entityId: row.entityId }, {
      entityId: row.entityId,
      name: row.name,
      ssoUrl: row.ssoUrl,
      certificate: row.certificate,
      emailAttribute: row.emailAttribute,
      displayNameAttribute: row.displayNameAttribute,
      status: newStatus,
      sortOrder: row.sortOrder,
      remark: row.remark,
    });
    ElMessage.success('操作成功');
    gridApi.query();
  } catch (error) {
    logger.warn('切换 SAML IdP 状态失败: {}', error);
  }
}

async function handleDelete(row: SamlIdpConfigVO) {
  if (!row.entityId) return;
  try {
    await ElMessageBox.confirm(
      `确认删除 IdP "${row.name ?? row.entityId}"？此操作不可恢复。`,
      '确认删除',
      { type: 'warning' },
    );
  } catch {
    return;
  }
  try {
    await deleteApi({ entityId: row.entityId });
    ElMessage.success(t('page.deleteSuccess'));
    gridApi.query();
  } catch (error) {
    logger.warn('删除 SAML IdP 配置失败: {}', error);
  }
}
</script>

<template>
  <Page auto-content-height>
    <Grid table-title="SAML IdP 配置管理">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleAdd">创建 IdP 配置</ElButton>
      </template>
    </Grid>

    <!-- 创建/编辑弹窗 -->
    <Modal :title="modalTitle">
      <ElForm
        ref="formRef"
        :model="formData"
        :rules="rules"
        label-width="130px"
        label-position="right"
      >
        <ElFormItem label="Entity ID" prop="entityId">
          <ElInput v-model="formData.entityId" placeholder="如 https://idp.example.com/entity" :disabled="isEdit" />
        </ElFormItem>
        <ElFormItem label="IdP 名称" prop="name">
          <ElInput v-model="formData.name" placeholder="如 企业微信 SAML" />
        </ElFormItem>
        <ElFormItem label="SSO 端点" prop="ssoUrl">
          <ElInput v-model="formData.ssoUrl" placeholder="如 https://idp.example.com/sso" />
        </ElFormItem>
        <ElFormItem label="公钥证书">
          <ElInput
            v-model="formData.certificate"
            type="textarea"
            :rows="4"
            placeholder="-----BEGIN CERTIFICATE-----&#10;..."
          />
        </ElFormItem>
        <ElFormItem label="邮箱属性名">
          <ElInput v-model="formData.emailAttribute" placeholder="默认 email" />
        </ElFormItem>
        <ElFormItem label="显示名属性">
          <ElInput v-model="formData.displayNameAttribute" placeholder="默认 displayName" />
        </ElFormItem>
        <ElFormItem label="状态">
          <ElRadioGroup v-model="formData.status">
            <ElRadioButton value="ENABLED">已启用</ElRadioButton>
            <ElRadioButton value="DISABLED">已停用</ElRadioButton>
          </ElRadioGroup>
        </ElFormItem>
        <ElFormItem label="排序">
          <ElInputNumber v-model="formData.sortOrder" :min="0" :max="999" />
        </ElFormItem>
        <ElFormItem label="备注">
          <ElInput v-model="formData.remark" type="textarea" :rows="2" placeholder="备注说明" />
        </ElFormItem>
      </ElForm>
    </Modal>
  </Page>
</template>
